/**
 * The client's metric vocabulary mirrors the server engine:
 * shared/metric-matrix.json is regenerated by a backend test from
 * app/services/metrics.py, so a measure, unit, valid dimension, permission
 * need, relative period or grain changed on either side fails here. Plus the
 * display helpers: numbers, periods, dimension names, colours, keys.
 */
import { describe, it, expect } from 'vitest';
import matrix from '../../../../shared/metric-matrix.json';
import {
  ARCHIVED_NEEDS,
  archivedNeeds,
  DIMENSION_KINDS,
  dimensionLabel,
  dimensionNeeds,
  FALLBACK_PALETTE,
  formatMetric,
  GRAINS,
  isDimensionHidden,
  isValidDimension,
  MATRIX,
  MEASURES,
  normaliseKey,
  OTHER_KEY,
  periodLabel,
  queryUnit,
  RELATIVE_PERIODS,
  resolvedPeriodLabel,
  UNIT_LABELS,
  widgetColor,
} from '../metrics';
import { SKILL_COLOR_SWATCHES } from '../colorSwatches';
import type { DimensionKind, Measure } from '@/types';

const sorted = (values: Iterable<string>) => [...values].sort();

describe('metric matrix mirror', () => {
  it('names exactly the server measures, with their units', () => {
    expect(sorted(MEASURES.map((m) => m.key))).toEqual(sorted(Object.keys(matrix.measures)));
    for (const measure of MEASURES) {
      expect(measure.unit).toBe(matrix.measures[measure.key as keyof typeof matrix.measures].unit);
    }
  });

  it('accepts the same dimensions per measure', () => {
    for (const [measure, spec] of Object.entries(matrix.measures)) {
      expect(sorted(MATRIX[measure as Measure])).toEqual(sorted(spec.dimensions));
      expect(new Set(MATRIX[measure as Measure]).size).toBe(MATRIX[measure as Measure].length);
    }
  });

  it('names every dimension kind the matrix uses', () => {
    const used = new Set(Object.values(matrix.measures).flatMap((m) => m.dimensions));
    expect(sorted(DIMENSION_KINDS.map((d) => d.key))).toEqual(sorted(used));
  });

  it('asks for the same permissions', () => {
    expect(dimensionNeeds('person')).toBe(matrix.needs.person);
    expect(ARCHIVED_NEEDS).toBe(matrix.needs.archived);
    for (const { key } of DIMENSION_KINDS) {
      if (key !== 'person') expect(dimensionNeeds(key)).toBeNull();
    }
  });

  it('offers the same relative periods and grains, in order', () => {
    expect(RELATIVE_PERIODS.map((p) => p.key)).toEqual(matrix.relative_periods);
    expect(GRAINS.map((g) => g.key)).toEqual(matrix.grains);
  });
});

describe('matrix helpers', () => {
  it('tells valid dimensions apart', () => {
    expect(isValidDimension('booked_weeks', 'person')).toBe(true);
    expect(isValidDimension('people_booked', 'period')).toBe(false);
    expect(isValidDimension('project_volume', 'period')).toBe(false);
    expect(isValidDimension('phase_count', 'phase_type')).toBe(true);
    expect(isValidDimension('project_count', 'team')).toBe(false);
  });

  it('needs views.archived only to include archived projects', () => {
    expect(archivedNeeds(undefined)).toBeNull();
    expect(archivedNeeds('exclude')).toBeNull();
    expect(archivedNeeds('include')).toBe('views.archived');
    expect(archivedNeeds('only')).toBe('views.archived');
  });

  it('labels the relative periods', () => {
    expect(RELATIVE_PERIODS.map((p) => p.label)).toEqual([
      'This year',
      'Last year',
      'This quarter',
      'Last quarter',
      'Last 12 months',
      'All time',
    ]);
  });

  it('derives a query’s unit from its measure, or percent', () => {
    expect(queryUnit({ measure: 'booked_weeks' })).toBe('weeks');
    expect(queryUnit({ measure: 'project_count', percent_of: 'total' })).toBe('percent');
    expect(queryUnit({ measure: 'unknown' as Measure })).toBe('count');
  });
});

describe('formatMetric', () => {
  it('shows weeks and days with one decimal', () => {
    expect(formatMetric(12, 'weeks')).toBe('12.0');
    expect(formatMetric(3.456, 'days')).toBe('3.5');
    expect(formatMetric(1234.5, 'weeks')).toBe('1,234.5');
  });

  it('shows counts as integers', () => {
    expect(formatMetric(7, 'projects')).toBe('7');
    expect(formatMetric(7.6, 'count')).toBe('8');
    expect(formatMetric(3, 'people')).toBe('3');
    expect(formatMetric(2, 'phases')).toBe('2');
  });

  it('shows volumes with up to two decimals', () => {
    expect(formatMetric(1500, 'volume')).toBe('1,500');
    expect(formatMetric(12.345, 'volume')).toBe('12.35');
  });

  it('shows percentages with a thin space before %', () => {
    expect(formatMetric(12.5, 'percent')).toBe('12.5 %');
    expect(formatMetric(50, 'percent')).toBe('50 %');
  });

  it('follows number_format', () => {
    expect(formatMetric(12.34, 'weeks', { number_format: 'integer' })).toBe('12');
    expect(formatMetric(3, 'projects', { number_format: 'decimal' })).toBe('3.00');
    expect(formatMetric(12.5, 'weeks', { number_format: 'percent' })).toBe('12.5 %');
    expect(formatMetric(12.5, 'percent', { number_format: 'integer' })).toBe('13 %');
    expect(formatMetric(12.5, 'weeks', null)).toBe('12.5');
  });

  it('shows a dash for no value', () => {
    expect(formatMetric(null, 'weeks')).toBe('–');
    expect(formatMetric(undefined, 'weeks')).toBe('–');
    expect(formatMetric(Number.NaN, 'weeks')).toBe('–');
  });
});

describe('labels', () => {
  it('names a period: relative by its label, absolute by its dates', () => {
    expect(periodLabel({ relative: 'last_12_months' })).toBe('Last 12 months');
    expect(periodLabel(undefined)).toBe('This year');
    expect(periodLabel({ relative: 'someday' as never })).toBe('someday');
    expect(periodLabel({ from: '2026-01-01', to: '2026-12-31' })).toBe(
      resolvedPeriodLabel({ from: '2026-01-01', to: '2026-12-31' })
    );
    expect(resolvedPeriodLabel({ from: '2026-01-01', to: '2026-12-31' })).toMatch(/2026 – .*2026$/);
  });

  it('names dimensions: fields by name, built-ins by their instance label, periods by grain', () => {
    const fields = [{ id: 3, name: 'Project type' }];
    const settings = { project_field_labels: '{"customer":"Client","confirmed":"Signed"}' };
    expect(dimensionLabel({ kind: 'field', field_id: 3 }, fields, settings)).toBe('Project type');
    expect(dimensionLabel({ kind: 'field', field_id: 9 }, fields, settings)).toBe('Project field');
    expect(dimensionLabel({ kind: 'customer' }, fields, settings)).toBe('Client');
    expect(dimensionLabel({ kind: 'confirmed' }, fields, settings)).toBe('Signed');
    expect(dimensionLabel({ kind: 'customer' }, fields, null)).toBe('Customer');
    expect(dimensionLabel({ kind: 'period', grain: 'month' }, fields, null)).toBe('Month');
    expect(dimensionLabel({ kind: 'period', grain: 'decade' as never }, fields, null)).toBe('Period');
    expect(dimensionLabel({ kind: 'project_manager' }, fields, null)).toBe('Project manager');
    expect(dimensionLabel({ kind: 'mystery' as Exclude<DimensionKind, 'field' | 'period'> }, fields, null)).toBe(
      'mystery'
    );
  });

  it('hides the Customer dimension while the built-in field is hidden', () => {
    expect(isDimensionHidden('customer', { project_fields_hidden: '["customer"]' })).toBe(true);
    expect(isDimensionHidden('customer', null)).toBe(false);
    expect(isDimensionHidden('confirmed', { project_fields_hidden: '["customer"]' })).toBe(false);
  });

  it('has a word for every unit but percent', () => {
    expect(UNIT_LABELS.weeks).toBe('weeks');
    expect(UNIT_LABELS.count).toBe('bookings');
    expect(UNIT_LABELS.percent).toBe('');
  });
});

describe('widgetColor', () => {
  it('takes the value’s own colour first', () => {
    expect(widgetColor({ key: 4, label: 'Team A', color: '#123456' }, 0, ['a'])).toBe('#123456');
  });

  it('falls back to the palette by position, wrapping', () => {
    expect(widgetColor({ key: 4, label: 'X' }, 0, ['a', 'b'])).toBe('a');
    expect(widgetColor({ key: 5, label: 'Y' }, 3, ['a', 'b'])).toBe('b');
    expect(widgetColor(null, 1)).toBe(FALLBACK_PALETTE[1]);
    expect(widgetColor(null, 0, [])).toBe(FALLBACK_PALETTE[0]);
    expect(FALLBACK_PALETTE).toEqual(SKILL_COLOR_SWATCHES.map((s) => s.value));
  });

  it('gives "Other" its own colour when asked', () => {
    expect(widgetColor({ key: OTHER_KEY, label: 'Other' }, 2, ['a', 'b', 'c'], 'grey')).toBe('grey');
    expect(widgetColor({ key: OTHER_KEY, label: 'Other' }, 2, ['a', 'b', 'c'])).toBe('c');
  });
});

describe('normaliseKey', () => {
  it('compares numbers, booleans and texts in one form', () => {
    expect(normaliseKey('3')).toBe(3);
    expect(normaliseKey(3)).toBe(3);
    expect(normaliseKey('2.5')).toBe(2.5);
    expect(normaliseKey('true')).toBe(true);
    expect(normaliseKey('false')).toBe(false);
    expect(normaliseKey(true)).toBe(true);
    expect(normaliseKey('Acme')).toBe('Acme');
    expect(normaliseKey('2026-Q1')).toBe('2026-Q1');
    expect(normaliseKey(null)).toBeNull();
    expect(normaliseKey(undefined)).toBeNull();
  });
});
